<script setup lang="ts">
import { onMounted, ref } from 'vue';
import DashboardLayout from '@/layouts/DashboardLayout.vue';
import ApiAlert from '@/components/ApiAlert.vue';
import { api, errorMessage } from '@/api/client';
import type { ApiResponse, MembershipApplication, Pagination } from '@/types/api';
const fieldLabels: Record<string, string> = { reference: 'Reference', email: 'Email', phone: 'Phone', location: 'Location / Address', previousName: 'Previous name', graduationYear: 'Graduation year', studentIndexNumber: 'Student / index number', lastClassAttended: 'Last class attended', verificationInformation: 'Verification information', status: 'Status', reviewedBy: 'Reviewing administrator ID', reviewedAt: 'Reviewed at', activatedAt: 'Account activated at', rejectionReason: 'Rejection explanation', activationDeliveryStatus: 'Invitation delivery', activationDeliveryAt: 'Delivery attempted at' };
const applications = ref<MembershipApplication[]>([]), selected = ref<MembershipApplication | null>(null), pagination = ref<Pagination | null>(null);
const search = ref(''), status = ref('PENDING'), page = ref(1), loading = ref(false), busy = ref(false), error = ref(''), notice = ref(''), notes = ref(''), rejectionReason = ref(''), link = ref('');
async function load() { loading.value = true; error.value = ''; try { const response = await api.get<ApiResponse<MembershipApplication[]>>('/membership/applications', { params: { page: page.value, limit: 15, search: search.value || undefined, status: status.value || undefined } }); applications.value = response.data.data; pagination.value = response.data.pagination; } catch (e) { error.value = errorMessage(e); } finally { loading.value = false; } }
async function open(id: string) { busy.value = true; error.value = ''; link.value = ''; notes.value = ''; rejectionReason.value = ''; try { selected.value = (await api.get<ApiResponse<MembershipApplication>>(`/membership/applications/${id}`)).data.data; } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
function showDelivery(delivery?: { status: string; message: string }) { notice.value = ''; error.value = ''; if (delivery?.status === 'failed') error.value = delivery.message; else notice.value = delivery?.message || 'Membership decision recorded.'; }
async function review(decision: 'APPROVED' | 'REJECTED') { if (!selected.value) return; busy.value = true; error.value = ''; notice.value = ''; link.value = ''; try { const response = await api.patch<ApiResponse<{ application: MembershipApplication; developmentActivationLink?: string; delivery?: { status: string; message: string } }>>(`/membership/applications/${selected.value.id}/review`, { decision, notes: notes.value || undefined, rejectionReason: rejectionReason.value || undefined }); selected.value = response.data.data.application; link.value = response.data.data.developmentActivationLink || ''; await load(); showDelivery(response.data.data.delivery); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
async function activation(revoke = false) { if (!selected.value) return; busy.value = true; error.value = ''; notice.value = ''; link.value = ''; try { const url = `/membership/applications/${selected.value.id}/activation`; if (revoke) { await api.delete(url); notice.value = 'Activation invitation revoked.'; } else { const response = await api.post<ApiResponse<{ developmentActivationLink?: string; delivery: { status: string; message: string } }>>(url); link.value = response.data.data.developmentActivationLink || ''; showDelivery(response.data.data.delivery); } selected.value = (await api.get<ApiResponse<MembershipApplication>>(`/membership/applications/${selected.value.id}`)).data.data; } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
function filter() { page.value = 1; void load(); }
onMounted(load);
</script>
<template><DashboardLayout><section class="mx-auto max-w-6xl space-y-6 p-5 lg:p-10"><div class="flex flex-wrap items-center justify-between gap-4"><h1 class="text-h1">Membership applications</h1><RouterLink to="/admin/membership/qr" class="primary-button">Membership QR code</RouterLink></div><ApiAlert :message="error"/><ApiAlert :message="notice" kind="success"/><form class="flex flex-wrap items-end gap-4 border bg-white p-5" @submit.prevent="filter"><div><label for="application-search" class="field-label">Search name, email or reference</label><input id="application-search" v-model.trim="search" maxlength="150" class="field-input"></div><div><label for="application-status" class="field-label">Status</label><select id="application-status" v-model="status" class="field-input"><option value="">All</option><option>PENDING</option><option>APPROVED</option><option>REJECTED</option></select></div><button class="primary-button" :disabled="loading">Search</button></form>
<p v-if="loading" role="status">Loading applications…</p><div v-else class="overflow-x-auto border bg-white"><table class="w-full text-left"><thead class="bg-slate-50"><tr><th class="p-4">Applicant</th><th class="p-4">Year</th><th class="p-4">Status</th><th class="p-4">Account</th><th class="p-4">Details</th></tr></thead><tbody><tr v-for="item in applications" :key="item.id" class="border-t"><td class="p-4">{{ item.fullName }}<span class="block text-xs text-secondary">{{ item.email }}</span></td><td class="p-4">{{ item.graduationYear }}</td><td class="p-4">{{ item.status }}</td><td class="p-4">{{ item.activatedAt ? 'Activated' : 'Not activated' }}</td><td class="p-4"><button class="underline" :disabled="busy" @click="open(item.id)">Review details</button></td></tr><tr v-if="!applications.length"><td colspan="5" class="p-6">No matching applications.</td></tr></tbody></table></div><nav class="flex flex-wrap items-center gap-4" aria-label="Application pages"><button class="secondary-button" :disabled="page <= 1 || loading" @click="page--; load()">Previous</button><span>Page {{ page }} · {{ pagination?.total ?? 0 }} applications</span><button class="secondary-button" :disabled="!pagination || page >= pagination.totalPages || loading" @click="page++; load()">Next</button></nav>
<section v-if="selected" class="space-y-5 border bg-white p-6"><div class="flex justify-between"><h2 class="text-h2">{{ selected.fullName }}</h2><button class="underline" @click="selected = null; link = ''">Close</button></div><dl class="grid gap-4 sm:grid-cols-2"><div v-for="field in ['reference','email','phone','location','previousName','graduationYear','studentIndexNumber','lastClassAttended','verificationInformation','status','reviewedBy','reviewedAt','activatedAt','rejectionReason','activationDeliveryStatus','activationDeliveryAt'] as const" :key="field"><dt class="text-sm font-semibold">{{ fieldLabels[field] }}</dt><dd class="whitespace-pre-wrap break-words text-secondary">{{ selected[field] || '—' }}</dd></div></dl>
<form v-if="selected.status === 'PENDING'" class="space-y-4 border-t pt-4" @submit.prevent="review('APPROVED')"><label for="review-notes" class="field-label">Private verification notes</label><textarea id="review-notes" v-model.trim="notes" class="field-input" maxlength="2000"></textarea><label for="reject-reason" class="field-label">Applicant-facing rejection explanation (required to reject)</label><textarea id="reject-reason" v-model.trim="rejectionReason" class="field-input" maxlength="2000"></textarea><div class="flex flex-wrap gap-4"><button class="primary-button" :disabled="busy">Approve membership</button><button type="button" class="secondary-button" :disabled="busy || rejectionReason.length < 3" @click="review('REJECTED')">Reject application</button></div></form>
<div v-if="selected.status === 'APPROVED' && !selected.activatedAt" class="flex flex-wrap gap-4"><button class="primary-button" :disabled="busy" @click="activation()">Reissue activation invitation</button><button class="secondary-button" :disabled="busy" @click="activation(true)">Revoke invitation</button></div>
<section v-if="link" class="space-y-3 border border-amber-300 bg-amber-50 p-4"><p class="font-semibold">Development only · private activation invitation</p><p>Share only with the verified applicant. The link is shown here once and is not stored in this browser. In email delivery mode, the applicant receives the invitation directly and no link is shown here.</p><label for="private-invitation" class="field-label">Private invitation link</label><textarea id="private-invitation" readonly class="field-input" rows="3" :value="link"></textarea></section>
<h3 class="text-h2">Application history</h3><ol class="space-y-4"><li v-for="event in selected.history" :key="event.id" class="border-t pt-3"><p class="font-semibold">{{ event.action }} · {{ new Date(event.createdAt).toLocaleString() }}</p><p v-if="event.actorId" class="text-xs">Actor: {{ event.actorId }}</p><p class="whitespace-pre-wrap">{{ event.notes }}</p><details v-if="event.snapshot"><summary class="cursor-pointer text-sm">Submitted information at this step</summary><pre class="overflow-x-auto text-xs">{{ JSON.stringify(event.snapshot, null, 2) }}</pre></details></li></ol>
</section></section></DashboardLayout></template>
